arguments.rule_content:
title: Cobalt Strike Beacon C2 Activity
id: ET-TROJAN-CobaltStrike
status: stable
description: Detects Cobalt Strike Beacon command and control activity
reference: url, https://www.fireeye.com/cyber-threats/cobalt-strike.html
author: Emerging Threats
date: 2022/01/01
modified: 2024/01/01
rule: 
    alert tcp any any -> any 443 ( 
        msg:"ET TROJAN Cobalt Strike Beacon C2 Activity"; 
        flow:to_server; 
        content:"BEACON"; 
        http_header; 
        fast_pattern; 
        content:"User-Agent|3a| "; 
        http_header; 
        pcre:!"/User-Agent\[^\r\n]*Mozilla\/5\.0\(compatible\(;[\s\S]*BEACON[\s\S]*\)\)"/U"; 
        content:!"Accept-Encoding|3a| gzip"; 
        http_header;
        metadata:policy security-ips drop, policy max-detect-ips drop, service http;
        reference:cve,CVE-2018-0000; 
        classtype:trojan-activity; 
        sid:20264781; 
        rev:5;)
